// 'name?: T | null' means the backend may send null: do not assume the field is there.

export type PunchType = 'IN' | 'OUT' | 'BREAK_START' | 'BREAK_END'

export interface Punch {
  id: string
  employee_id: string
  type: PunchType
  timestamp: string
}

export interface Shift {
  id: string
  employee_id: string
  start: string
  end: string
  location_id: string
}

export interface Timecard {
  id: string
  employee_id: string
  work_date: string
  punches: Punch[]
  shifts: Shift[]
  notes?: string | null // UNTRUSTED free text: show as plain text, never as HTML
}

export type ExceptionType =
  | 'MISSED_PUNCH'
  | 'OVERTIME_RISK'
  | 'SCHEDULE_CONFLICT'
  | 'POLICY_BREACH'

export type Severity = 'LOW' | 'MEDIUM' | 'HIGH'

export type FixAction =
  | 'ADD_PUNCH'
  | 'EDIT_PUNCH'
  | 'DEDUCT_BREAK'
  | 'REASSIGN_SHIFT'
  | 'FLAG_FOR_MANAGER'
  | 'NO_CHANGE'

export interface FieldChange {
  target_id: string
  field: string // a label such as 'punch.OUT', not a fixed list
  old?: string | null
  new?: string | null
}

export interface Fix {
  action: FixAction
  changes: FieldChange[]
}

export interface DetectedException {
  id: string
  type: ExceptionType
  severity: Severity
  employee_id: string
  timecard_id: string
  work_date: string
  evidence: Record<string, unknown> // keys differ per exception type
  policy_refs: string[]
  baseline_fix?: Fix | null // the rule-based fix; null when the policy has none
  status: 'OPEN' | 'PROPOSED' | 'ESCALATED' | 'RESOLVED'
}

export interface PolicyCitation {
  clause_id: string
  quote: string
  score: number
}

export interface Violation {
  code: string
  message: string
  clause_id?: string | null
}

export interface ValidationResult {
  passed: boolean
  violations: Violation[]
}

export type ProposalSource = 'LLM' | 'RULES_FALLBACK'

export interface Proposal {
  id: string
  exception_id: string
  fix: Fix
  rationale: string // max 400 characters; plain language
  citations: PolicyCitation[]
  confidence: number // 0 to 1
  source: ProposalSource
  model?: string | null // null for rule-based fixes and escalations
  prompt_version: string
  validation?: ValidationResult | null // null for escalations
  status: 'PENDING_REVIEW' | 'APPROVED' | 'REJECTED' | 'ESCALATED'
}

export interface Decision {
  id: string
  proposal_id: string
  decision: 'APPROVE' | 'REJECT'
  manager_id: string
  comment?: string | null
  decided_at: string
}

export interface AuditEvent {
  id: string
  ts: string
  actor: string // 'system', 'llm' or a manager id
  event_type: string
  entity_type: string
  entity_id: string
  payload: Record<string, unknown> // keys differ per event_type
}

// ---------------------------------------------------------------------------
// PROPOSED API shapes. Not in models.py. The backend owner may change them.
// ---------------------------------------------------------------------------

export interface CaseListItem {
  exception: DetectedException
  proposal?: Proposal | null
}

export interface CaseDetail {
  timecard: Timecard
  exception: DetectedException
  proposal?: Proposal | null
  decision?: Decision | null
  audit_events: AuditEvent[]
}

export interface DecisionRequest {
  decision: 'APPROVE' | 'REJECT'
  manager_id: string
  comment?: string | null
}
